package com.akitaattribute.mobfarmblock.block;
import com.akitaattribute.mobfarmblock.behavior.*; import com.mojang.serialization.MapCodec; import net.minecraft.block.*; import net.minecraft.block.entity.BlockEntity; import net.minecraft.entity.player.PlayerEntity; import net.minecraft.item.ItemStack; import net.minecraft.util.*; import net.minecraft.util.hit.BlockHitResult; import net.minecraft.util.math.BlockPos; import net.minecraft.world.World;
public class MobFarmBlock extends BlockWithEntity { public static final MapCodec<MobFarmBlock> CODEC=createCodec(MobFarmBlock::new); public MobFarmBlock(Settings s){super(s);} @Override public BlockEntity createBlockEntity(BlockPos pos, BlockState state){return new MobFarmBlockEntity(pos,state);} @Override protected MapCodec<? extends BlockWithEntity> getCodec(){return CODEC;} @Override protected BlockRenderType getRenderType(BlockState state){return BlockRenderType.MODEL;} @Override protected ItemActionResult onUseWithItem(ItemStack stack, BlockState state, World world, BlockPos pos, PlayerEntity player, Hand hand, BlockHitResult hit){ if(world.isClient)return ItemActionResult.SUCCESS; if(world.getBlockEntity(pos) instanceof MobFarmBlockEntity be){var stored=be.getStored(); var r=BehaviorRegistry.get(stored.mobId).interact(new MobFarmContext(world,pos,player,stack,stored,world.random)); if(r.isAccepted()) be.setStored(stored); return r.isAccepted()?ItemActionResult.SUCCESS:ItemActionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;} return ItemActionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;} public static ActionResult attack(World world, BlockPos pos, PlayerEntity player){ if(world.isClient)return ActionResult.SUCCESS; if(world.getBlockEntity(pos) instanceof MobFarmBlockEntity be){var s=be.getStored(); var r=BehaviorRegistry.get(s.mobId).attack(new MobFarmContext(world,pos,player,player.getMainHandStack(),s,world.random)); if(r==AttackResult.SUCCESS){be.setStored(s); return ActionResult.SUCCESS;}} return ActionResult.PASS;} }
